-- =====================================================================
-- 아낄맵 시연용 시드 데이터 (지라 S15P11A508-144 / B1)
-- 원본: dummy_data.csv sha256[:16]=716d33dfcec91c7d · 거래 1866건 · 2026년 1년치 · 페르소나 1명
-- 생성기: PoC-AI/ai-agent experiments/make_seed_sql.py (수정은 생성기에서, 이 파일 직접 편집 금지)
-- 전제: 백엔드 앱이 한 번 떠서 테이블이 생성된 상태. PostGIS 확장 필요.
--       대상 사용자가 **이미 가입되어 있어야 한다** — 카테고리 11종을 그 계정 것으로 쓴다.
-- 사용: psql -h localhost -U <user> -d <db> -v ON_ERROR_STOP=1 -f seed.sql
--
-- ⚠ 대상 사용자의 기존 거래내역·내 장소를 **삭제**한다. 버려도 되는 계정에만 쓸 것.
--   users / category 는 건드리지 않는다(실계정 보호).
-- =====================================================================

-- ▼▼▼ 여기만 수정 ▼▼▼
--   대상 사용자의 user_id. 0 은 존재하지 않는 값이라 이대로 실행하면 아래 검사에서 멈춘다.
--   SELECT user_id, nickname FROM users ORDER BY user_id; 로 확인 후 바꿀 것.
--   psql -v TARGET_USER_ID=27 로 밖에서 넘겨도 된다(그 경우 아래 기본값은 무시된다).
\if :{?TARGET_USER_ID}
\else
  \set TARGET_USER_ID 0
\endif
-- ▲▲▲ 여기만 수정 ▲▲▲

BEGIN;

-- 0) 선행 조건: 대상 사용자와 카테고리 11종이 존재해야 한다.
SET LOCAL my.target_user_id = :'TARGET_USER_ID';
DO $seed$
DECLARE
    v_user_id  BIGINT := current_setting('my.target_user_id')::BIGINT;
    v_missing  TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM users WHERE user_id = v_user_id) THEN
        RAISE EXCEPTION '존재하지 않는 user_id 입니다: % — 파일 상단 TARGET_USER_ID 를 확인하세요.', v_user_id;
    END IF;

    SELECT string_agg(m.name, ', ' ORDER BY m.name) INTO v_missing
    FROM (VALUES
        ('음식점'),
        ('카페·간식'),
        ('편의점·마트'),
        ('쇼핑'),
        ('여가'),
        ('교통'),
        ('건강·의료'),
        ('생활'),
        ('미용'),
        ('교육'),
        ('기타')
    ) AS m(name)
    WHERE NOT EXISTS (
        SELECT 1 FROM category c WHERE c.user_id = v_user_id AND c.name = m.name);

    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'user_id=% 에게 없는 카테고리: % — 기본 카테고리가 생성된 계정인지 확인하세요.',
            v_user_id, v_missing;
    END IF;
END
$seed$;

-- 1) 대상 사용자의 기존 데이터 정리. users·category 는 절대 지우지 않는다.
--    (알림 장소 notification_place 는 남는다 — 거래와 FK 관계가 없다.)
DELETE FROM transaction_history WHERE user_id = :TARGET_USER_ID;
DELETE FROM my_place WHERE user_id = :TARGET_USER_ID;

-- 2) 시드의 카테고리 번호 → 이름. 실제 category_id 는 5)에서 이름으로 찾는다.
CREATE TEMP TABLE seed_category_map (
    seed_category_id BIGINT PRIMARY KEY,
    category_name    VARCHAR(20) NOT NULL
) ON COMMIT DROP;

-- 3) my_place ('집' 이름은 배달 판별·집 의존 사실의 앵커 — 설계 문서 §3.1)
--    id 는 명시하지 않는다 — 전역 PK 라 다른 사용자 행과 충돌한다.

-- 4) 거래 1866건을 임시 테이블에 그대로 싣는다(원본 카테고리 번호 유지).
CREATE TEMP TABLE seed_transaction (
    seed_transaction_id BIGINT PRIMARY KEY,
    seed_category_id    BIGINT NOT NULL,
    datetime            TIMESTAMPTZ NOT NULL,
    amount              BIGINT NOT NULL,
    type                TEXT NOT NULL,
    transaction_name    TEXT NOT NULL,   -- staging 은 CSV 를 그대로 받는다. 길이 제약은 최종 테이블이 판정한다.
    payment_method      TEXT,
    memo                TEXT,
    address             TEXT,
    b_code              VARCHAR(20),
    region_1depth_name  TEXT,
    region_2depth_name  TEXT,
    region_3depth_name  TEXT,
    coordinate          geometry(Point, 4326)
) ON COMMIT DROP;

-- 5) 대상 사용자 + 그 사용자의 실제 category_id 로 변환해 적재한다.
--    소득은 마이그레이션 003 의 CHECK 에 따라 카테고리·결제수단을 비운다.
--    ※ JOIN 은 원본 카테고리 번호로 걸리므로 소득 행도 매칭된다 — 비우는 건 SELECT 단계다.
--      (staging 에서 비우면 조인이 끊겨 소득 행이 조용히 사라진다.)
    user_id, category_id, datetime, amount, type, transaction_name,
    payment_method, branch, memo, address, b_code,
    region_1depth_name, region_2depth_name, region_3depth_name, coordinate
)
SELECT
    :TARGET_USER_ID,
    CASE WHEN s.type = 'INCOME' THEN NULL ELSE c.category_id END,
    s.datetime,
    s.amount,
    s.type,
    s.transaction_name,
    CASE WHEN s.type = 'INCOME' THEN NULL ELSE s.payment_method END,
    NULL,  -- branch: 실서비스 API 가 채우지 않는 컬럼
    s.memo,
    s.address,
    s.b_code,
    s.region_1depth_name,
    s.region_2depth_name,
    s.region_3depth_name,
    s.coordinate
FROM seed_transaction s
JOIN seed_category_map m ON m.seed_category_id = s.seed_category_id
JOIN category c ON c.user_id = :TARGET_USER_ID AND c.name = m.category_name
ORDER BY s.seed_transaction_id;

COMMIT;

-- ===================== 체크섬 (적재 후 실행, 전부 OK 여야 함) =====================
SELECT * FROM (VALUES
  ('행수: my_place=2', CASE WHEN (SELECT COUNT(*) FROM my_place WHERE user_id = :TARGET_USER_ID) = 2 THEN 'OK' ELSE 'FAIL' END),
  ('행수: 거래=1866', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID) = 1866 THEN 'OK' ELSE 'FAIL' END),
  ('행수: 지출=1842', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='EXPENSE') = 1842 THEN 'OK' ELSE 'FAIL' END),
  ('행수: 소득=24', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='INCOME') = 24 THEN 'OK' ELSE 'FAIL' END),
  ('수입 합계=25150500', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='INCOME') = 25150500 THEN 'OK' ELSE 'FAIL' END),
  ('지출 합계=25136100', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='EXPENSE') = 25136100 THEN 'OK' ELSE 'FAIL' END),
  ('재량비=16490200 (obs07 대조)', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='EXPENSE' AND payment_method NOT IN ('자동이체','계좌이체')) = 16490200 THEN 'OK' ELSE 'FAIL' END),
  ('소득: 카테고리·결제수단 전부 NULL', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type='INCOME' AND (category_id IS NOT NULL OR payment_method IS NOT NULL)) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('지출: 카테고리·결제수단 결측 0', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND type<>'INCOME' AND (category_id IS NULL OR payment_method IS NULL)) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리가 전부 대상 사용자 소유', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.user_id <> t.user_id) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('branch 전부 NULL', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND branch IS NOT NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('b_code 결측 0', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND b_code IS NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('좌표 결측 0', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE user_id = :TARGET_USER_ID AND coordinate IS NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('기간 시작=2026-01-01', CASE WHEN (SELECT MIN(datetime AT TIME ZONE 'Asia/Seoul')::date FROM transaction_history WHERE user_id = :TARGET_USER_ID) = DATE '2026-01-01' THEN 'OK' ELSE 'FAIL' END),
  ('기간 끝=2026-12-31', CASE WHEN (SELECT MAX(datetime AT TIME ZONE 'Asia/Seoul')::date FROM transaction_history WHERE user_id = :TARGET_USER_ID) = DATE '2026-12-31' THEN 'OK' ELSE 'FAIL' END),
  ('''집'' 장소 존재', CASE WHEN (SELECT COUNT(*) FROM my_place WHERE user_id = :TARGET_USER_ID AND place_name = '집') = 1 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 음식점=449건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '음식점') = 449 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 카페·간식=496건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '카페·간식') = 496 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 편의점·마트=242건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '편의점·마트') = 242 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 쇼핑=28건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '쇼핑') = 28 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 여가=35건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '여가') = 35 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 교통=500건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '교통') = 500 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 건강·의료=4건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '건강·의료') = 4 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 생활=70건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '생활') = 70 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 미용=8건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '미용') = 8 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 교육=0건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '교육') = 0 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 기타=10건', CASE WHEN (SELECT COUNT(*) FROM transaction_history t JOIN category c ON c.category_id = t.category_id WHERE t.user_id = :TARGET_USER_ID AND c.name = '기타') = 10 THEN 'OK' ELSE 'FAIL' END)
) AS checks(item, result);
